    ["Paladin"] = "Paladin",
    ["Party/raid chat: off, finished objectives, or every step. Also says when a quest is ready."] = "Discussion de groupe/raid : désactivé, objectifs terminés, ou chaque étape. Indique aussi quand une quête est prête.",
    ["Paused"] = "En pause",
    ["Pet trainers"] = "Maîtres des familiers",
    ["Pick the basics now; everything can be changed later under Settings. Done closes this page. Tips: /walkmap guide"] = "Choisissez l'essentiel maintenant ; tout se change plus tard dans Réglages. Terminé ferme cette page. Astuces : /walkmap guide",
    ["Places"] = "Lieux",
    ["Places > Other: Herbs and Mining show known QuestieDB node locations."] = "Lieux > Autre : Herbes et Minage montrent les gisements connus de QuestieDB.",
    ["Player"] = "Joueur",
    ["Player marker halo"] = "Halo autour du joueur",
    ["Please write in the comments on WalkMap's CurseForge page. A screenshot or the Debug report (Settings > Controller & help) helps a lot."] = "Écrivez dans les commentaires de la page CurseForge de WalkMap. Une capture ou le rapport de débogage (Réglages > Manette & aide) aide beaucoup.",
